// SwarmMeshNetwork.cpp#include "SwarmMeshNetwork.h"void SwarmMeshNetwork::RegisterDroneNode(NPC* pDrone) {    if (!pDrone)        return;    // Ensure no duplicate registrations    if (std::find(m_meshNodes.begin(), m_meshNodes.end(), pDrone) == m_meshNodes.end()) {        m_meshNodes.push_back(pDrone);        RecalculateMeshTopology();    }}void SwarmMeshNetwork::UnregisterDroneNode(NPC* pDrone) {    if (!pDrone)        return;    auto it = std::find(m_meshNodes.begin(), m_meshNodes.end(), pDrone);    if (it != m_meshNodes.end()) {        m_meshNodes.erase(it);        RecalculateMeshTopology();    }}void SwarmMeshNetwork::RecalculateMeshTopology() {    size_t nodeCount = m_meshNodes.size();    if (nodeCount IsDead()) {            // Apply the tracking multiplier to the turret/missile attributes            pDrone->SetDynamicAttributeModifier(AttrTrackingSpeed, m_activeTelemetry.globalTrackingMultiplier);            pDrone->SetDynamicAttributeModifier(AttrScanResolution, m_activeTelemetry.globalLockSpeedMultiplier);            // Ad-Hoc Proxy mechanic: High security system meshes share electronic load, negating player jam strength            float ewarResistanceBonus = 1.0f + (scalingFactor * 0.33f);            pDrone->SetDynamicAttributeModifier(AttrEwarResistance, ewarResistanceBonus);        }    }}